S = [list(input()) for _ in range(H)]

ans = float('inf')

for s in S:
    for i in range(W - K + 1):
        count = 0
        for j in range(K):
            if s[i + j] == '.':
                count += 1
        ans = min(ans, count)

S_t = [list(x) for x in zip(*S)]

